(function(r){let attempts=0;function mount(){if(++attempts>120)return;const g=r.PrecisionLab265?.state?.g;if(!g?.practice278){setTimeout(mount,500);return;}if(g.player.type!=='niko')return;const bar=[...document.querySelectorAll('button')].find(b=>b.textContent==='Restart duel')?.parentElement;if(!bar||bar.querySelector('[data-ddt285]'))return;const b=document.createElement('button'),note=document.createElement('span');b.dataset.ddt285='';b.textContent='Rehearse reverse DDT';b.onclick=()=>{const p=g.player,v=g.enemies.find(e=>e.hp>0);if(g.enemies.filter(e=>e.hp>0).length!==1||!v||p.act||p.down||p.stun||p.heldBy||p.hold||p.jump){note.textContent=' Restart a duel with one idle opponent first.';return;}const d=p.dir||1;v.act=null;v.stun=v.inv=v.wakeInv=v.grabImmune=0;v.x=p.x+d*45;v.y=p.y;if(!g.acquireGrab(v,true)){note.textContent=' Grab rules denied capture; weaken heavy/boss targets first.';return;}g.command('attack',d>0?{left:true}:{right:true});note.textContent=' Rear-away input queued through capture. Use Pause simulation and +1/+5/+10 frames.';};bar.append(b,note);}setTimeout(mount,2500);})(globalThis);
